using Microsoft.Data.Sqlite;
using BefundExplorer.Core.Search;
namespace BefundExplorer.Tests.Data;
internal sealed class TestDatabase : IDisposable
{
 public string Path { get; }
 public TestDatabase(){ Path=System.IO.Path.Combine(System.IO.Path.GetTempPath(),$"befundexplorer-{Guid.NewGuid():N}.sqlite"); using var con=new SqliteConnection($"Data Source={Path}"); con.Open(); using var cmd=con.CreateCommand(); cmd.CommandText="""
CREATE TABLE befunde (id INTEGER PRIMARY KEY, modalitaet TEXT NOT NULL, studienbeschreibung TEXT NOT NULL, titel TEXT NOT NULL, klinische_angaben TEXT NOT NULL, fragestellung TEXT NOT NULL, methodik TEXT NOT NULL, befund TEXT NOT NULL, beurteilung TEXT NOT NULL, originaltext TEXT NOT NULL, strukturstatus TEXT NOT NULL);
CREATE TABLE befunde_suchnormalisiert (id INTEGER PRIMARY KEY, studienbeschreibung TEXT NOT NULL, titel TEXT NOT NULL, klinische_angaben TEXT NOT NULL, fragestellung TEXT NOT NULL, methodik TEXT NOT NULL, befund TEXT NOT NULL, beurteilung TEXT NOT NULL, originaltext TEXT NOT NULL);
CREATE VIRTUAL TABLE befunde_volltext_v3 USING fts5(studienbeschreibung,titel,klinische_angaben,fragestellung,methodik,befund,beurteilung,originaltext,content='befunde',content_rowid='id',tokenize='unicode61 remove_diacritics 0',prefix='2 3 4');
CREATE VIRTUAL TABLE befunde_tolerant_v3 USING fts5(studienbeschreibung,titel,klinische_angaben,fragestellung,methodik,befund,beurteilung,originaltext,content='befunde_suchnormalisiert',content_rowid='id',tokenize='unicode61 remove_diacritics 0',prefix='2 3 4');
CREATE VIRTUAL TABLE befunde_teiltext_v3 USING fts5(studienbeschreibung,titel,klinische_angaben,fragestellung,methodik,befund,beurteilung,originaltext,content='befunde',content_rowid='id',tokenize='trigram case_sensitive 0');
"""; cmd.ExecuteNonQuery(); Add(con,1,"CT","CT Abdomen","CT Abdomen","Tumorsuche","Metastasen?","KM","Leber mit zwei hypodensen Läsionen.","Lebermetastasen wahrscheinlich.","vollstaendig"); Add(con,2,"MR","MRT LWS","MRT LWS","Schmerzen","Stenose?","3 T","L5/S1 mit ausgeprägtem Ödem und Spondylodiszitiszeichen.","Spondylodiszitis L5/S1.","vollstaendig"); Add(con,3,"MR","MRT Schädel","MRT Schädel","Metastasen Leber in Anamnese","Hirnmetastasen?","1,5 T","Kein fokaler Befund.","Kein Nachweis intrakranieller Metastasen.","vollstaendig"); Add(con,4,"CT","CT Thorax","CT Thorax","Kontrolle","Lunge?","KM","Die Leber ist im Oberbauch mit erfasst; kein fokaler Herd. Ferner Metastasen nicht sicher.","Unauffälliger Thorax.","ohne_explizite_beurteilung"); Add(con,5,"MR","MRT Handgelenk","MRT Handgelenk","SL-Läsion?","Bandläsion?","3 T","Verdacht auf Läsion des SL-Bandes; xxL5yy als Testtoken.","SL-Bandläsion.","vollstaendig"); Rebuild(con); }
 static void Add(SqliteConnection con,long id,string mod,string study,string title,string clinical,string question,string technique,string findings,string impression,string status){ var original=$"Klinische Angaben: {clinical}\nFragestellung: {question}\nBefund: {findings}\nBeurteilung: {impression}"; using var cmd=con.CreateCommand(); cmd.CommandText="INSERT INTO befunde VALUES($id,$m,$s,$t,$c,$q,$tech,$f,$i,$o,$st)"; cmd.Parameters.AddWithValue("$id",id);cmd.Parameters.AddWithValue("$m",mod);cmd.Parameters.AddWithValue("$s",study);cmd.Parameters.AddWithValue("$t",title);cmd.Parameters.AddWithValue("$c",clinical);cmd.Parameters.AddWithValue("$q",question);cmd.Parameters.AddWithValue("$tech",technique);cmd.Parameters.AddWithValue("$f",findings);cmd.Parameters.AddWithValue("$i",impression);cmd.Parameters.AddWithValue("$o",original);cmd.Parameters.AddWithValue("$st",status);cmd.ExecuteNonQuery(); string N(string x)=>GermanSearchNormalizer.NormalizeTolerant(x); using var n=con.CreateCommand(); n.CommandText="INSERT INTO befunde_suchnormalisiert VALUES($id,$s,$t,$c,$q,$tech,$f,$i,$o)"; n.Parameters.AddWithValue("$id",id);n.Parameters.AddWithValue("$s",N(study));n.Parameters.AddWithValue("$t",N(title));n.Parameters.AddWithValue("$c",N(clinical));n.Parameters.AddWithValue("$q",N(question));n.Parameters.AddWithValue("$tech",N(technique));n.Parameters.AddWithValue("$f",N(findings));n.Parameters.AddWithValue("$i",N(impression));n.Parameters.AddWithValue("$o",N(original));n.ExecuteNonQuery(); }
 static void Rebuild(SqliteConnection con){ foreach(var table in new[]{"befunde_volltext_v3","befunde_tolerant_v3","befunde_teiltext_v3"}){ using var cmd=con.CreateCommand(); cmd.CommandText=$"INSERT INTO {table}({table}) VALUES('rebuild')";cmd.ExecuteNonQuery(); } }
 public void Dispose(){try{File.Delete(Path);}catch{}}
}
